const rawItem = $input.first().json || {};
let data = {};

// Hỗ trợ đọc cả JSON chuẩn và text/plain (no-cors từ trình duyệt)
if (typeof rawItem.body === 'string') {
  try {
    data = JSON.parse(rawItem.body);
  } catch (e) {
    data = rawItem;
  }
} else if (rawItem.body && typeof rawItem.body === 'object') {
  data = rawItem.body;
} else {
  data = rawItem;
}

const decision = data.decision || (data.status === 'Đã duyệt gửi mẫu' ? 'approved' : 'rejected');
const status = data.status || (decision === 'approved' ? 'Đã duyệt gửi mẫu' : 'Từ chối');
const kocName = data.kocName || data.tiktokHandle || 'Bạn';
const rawHandle = (data.tiktokHandle || '').replace(/^@/, '');
const handle = rawHandle ? `@${rawHandle}` : '@koc';
const kocEmail = (data.kocEmail || data.email || '').trim();
const campaignName = data.campaignName || 'Chiến dịch Nhận Mẫu 0đ KOCity';
const applicationCode = data.applicationCode || data.code || '#KOC';
const selectedSample = data.selectedSample || 'Bộ sản phẩm mẫu 0đ';
const shippingCode = data.shippingCode || 'Đang cập nhật mã vận đơn';
const adminFeedback = data.adminFeedback || '';

const isEmailValid = Boolean(
  kocEmail &&
  kocEmail.includes('@') &&
  !kocEmail.endsWith('@kocity.local') &&
  !kocEmail.endsWith('@koctrend.local')
);

const isApproved = decision === 'approved' || decision === 'video_approved';

const defaultSubject = isApproved
  ? `🎉 [KOCity] Chúc mừng ${kocName}! Hồ sơ chiến dịch "${campaignName}" đã được DUYỆT`
  : `📩 [KOCity] Thông báo kết quả xét duyệt chiến dịch "${campaignName}"`;

const emailSubject = data.emailSubject || defaultSubject;
const emailHtml = data.emailHtml || `<p>Xin chào <b>${kocName}</b> (${handle}),</p><p>Trạng thái hồ sơ <b>${applicationCode}</b> cho chiến dịch <b>${campaignName}</b> đã được cập nhật sang: <b>${status}</b>.</p>`;
const emailPlainText = data.emailPlainText || `Xin chào ${kocName}, hồ sơ ${applicationCode} (${campaignName}) đã chuyển sang trạng thái: ${status}.`;

const telegramSummary =
  `${isApproved ? '✅ <b>[ĐÃ DUYỆT & GỬI EMAIL]</b>' : '❌ <b>[TỪ CHỐI & GỬI EMAIL]</b>'}\n\n` +
  `👤 <b>KOC:</b> ${kocName} (<code>${handle}</code>)\n` +
  `📧 <b>Email nhận:</b> <code>${kocEmail || 'Không có email'}</code>\n` +
  `🎯 <b>Chiến dịch:</b> ${campaignName}\n` +
  `📌 <b>Trạng thái:</b> <b>${status}</b>\n` +
  (shippingCode && isApproved ? `🚚 <b>Mã vận đơn:</b> <code>${shippingCode}</code>\n` : '') +
  (adminFeedback ? `💬 <b>Phản hồi Admin:</b> <i>${adminFeedback}</i>\n` : '') +
  `⏰ <b>Thời gian:</b> ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}`;

return [
  {
    json: {
      isEmailValid,
      isApproved,
      decision,
      status,
      kocName,
      handle,
      kocEmail,
      campaignName,
      applicationCode,
      selectedSample,
      shippingCode,
      adminFeedback,
      emailSubject,
      emailHtml,
      emailPlainText,
      telegramSummary
    }
  }
];
